"use client";

import { CalendarDays, Check, CheckCircle2, ChevronDown, ExternalLink, FolderKanban, Link2, ListChecks, NotebookPen, Pencil, Plus, Search, Trash2 } from "lucide-react";
import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { BrenDateTimeField } from "@/components/BrenDateTimeField";
import { createWorkspaceNote, createWorkspaceProject, createWorkspaceResource, createWorkspaceTask, deleteWorkspaceNote, deleteWorkspaceProject, deleteWorkspaceResource, deleteWorkspaceTask, toggleWorkspaceTask, updateWorkspaceNote, updateWorkspaceProject, updateWorkspaceResource, updateWorkspaceTask } from "@/app/admin/workspace/actions";

type Project = { id: string; title: string; description: string | null; category: string; status: string; due_at: string | null };
type Task = { id: string; project_id: string | null; title: string; description: string | null; status: string; priority: string; label: string | null; due_at: string | null; recurrence: string; related_url: string | null; };
type Note = { id: string; title: string; body: string; project_id: string | null; updated_at: string };
type Resource = { id: string; title: string; value: string; resource_type: string; description: string | null; project_id: string | null; };

const tabs = ["Overview", "Tasks", "Board", "Projects", "Calendar", "Notes", "Resources"] as const;
const metricTones: Record<string, string> = { purple: "bg-[var(--br-brand)]/10 text-[var(--br-brand)]", green: "bg-[var(--br-success)]/10 text-[var(--br-success)]", orange: "bg-[var(--br-action)]/10 text-[var(--br-action)]", blue: "bg-[var(--br-info)]/10 text-[var(--br-info)]" };
function dateInputValue(value: string | null) { return value ? new Date(value).toISOString().slice(0, 16) : ""; }

export function CreatorWorkspace({ projects, tasks, notes, resources }: { projects: Project[]; tasks: Task[]; notes: Note[]; resources: Resource[] }) {
  const [orderedTabs, setOrderedTabs] = useState<(typeof tabs)[number][]>([...tabs]);
  const [tab, setTab] = useState<(typeof tabs)[number]>("Overview");
  const [draggedTab, setDraggedTab] = useState<(typeof tabs)[number] | null>(null);
  const [query, setQuery] = useState("");
  const [taskFilter, setTaskFilter] = useState<"ALL" | "OPEN" | "TODAY" | "HIGH">("ALL");
  const [taskProjectId, setTaskProjectId] = useState("ALL");
  const [taskSort, setTaskSort] = useState<"RECENT" | "DUE">("RECENT");
  const [focusedProjectId, setFocusedProjectId] = useState<string | null>(null);
  const projectMap = useMemo(() => new Map(projects.map((project) => [project.id, project.title])), [projects]);
  const activeTasks = tasks.filter((task) => task.status !== "COMPLETED");
  const completedTasks = tasks.length - activeTasks.length;
  const visibleTasks = tasks.filter((task) => {
    const matchesQuery = `${task.title} ${task.description ?? ""} ${task.label ?? ""}`.toLowerCase().includes(query.toLowerCase());
    const matchesFilter = taskFilter === "ALL" || (taskFilter === "OPEN" && task.status !== "COMPLETED") || (taskFilter === "TODAY" && task.due_at && new Date(task.due_at).toDateString() === new Date().toDateString()) || (taskFilter === "HIGH" && ["HIGH", "URGENT"].includes(task.priority));
    const matchesProject = taskProjectId === "ALL" || (taskProjectId === "PERSONAL" ? task.project_id === null : task.project_id === taskProjectId);
    return matchesQuery && matchesFilter && matchesProject;
  }).sort((a, b) => taskSort === "DUE" ? (a.due_at ? new Date(a.due_at).getTime() : Number.MAX_SAFE_INTEGER) - (b.due_at ? new Date(b.due_at).getTime() : Number.MAX_SAFE_INTEGER) : 0);
  const today = new Date().toDateString();
  useEffect(() => {
    const saved = window.localStorage.getItem("brenup-workspace-tab-order");
    if (saved) { try { const parsed = JSON.parse(saved) as string[]; const next = tabs.filter((item) => parsed.includes(item)).sort((a, b) => parsed.indexOf(a) - parsed.indexOf(b)); if (next.length === tabs.length) { setOrderedTabs(next); setTab(next[0]); } } catch { /* use default order */ } }
  }, []);
  function reorderTabs(target: (typeof tabs)[number]) {
    if (!draggedTab || draggedTab === target) return;
    const next = [...orderedTabs]; const from = next.indexOf(draggedTab); const to = next.indexOf(target); next.splice(from, 1); next.splice(to, 0, draggedTab); setOrderedTabs(next); window.localStorage.setItem("brenup-workspace-tab-order", JSON.stringify(next)); setDraggedTab(null);
  }
  useEffect(() => {
    const addCloseButtons = () => document.querySelectorAll<HTMLElement>(".workspace-shell details[open]").forEach((detail) => {
      const popup = detail.querySelector<HTMLElement>(":scope > form, :scope > div");
      if (!popup || popup.querySelector(".workspace-popup-close")) return;
      const close = document.createElement("button");
      close.type = "button";
      close.className = "workspace-popup-close";
      close.setAttribute("aria-label", "Close popup");
      close.textContent = "×";
      popup.appendChild(close);
    });
    const closePopups = (event: MouseEvent) => {
      const target = event.target as Node;
      if (target instanceof Element && target.closest(".workspace-popup-close")) {
        target.closest("details")?.removeAttribute("open");
        return;
      }
      if (target instanceof Element && target.closest(".workspace-shell details")) return;
      document.querySelectorAll<HTMLElement>(".workspace-shell details[open]").forEach((detail) => detail.removeAttribute("open"));
    };
    document.addEventListener("click", closePopups);
    const observer = new MutationObserver(addCloseButtons);
    observer.observe(document.body, { attributes: true, subtree: true, attributeFilter: ["open"] });
    addCloseButtons();
    return () => { document.removeEventListener("click", closePopups); observer.disconnect(); };
  }, []);

  return <main className="workspace-shell min-w-0 space-y-5 pb-12">
    <header className="workspace-header flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--br-brand)]">Creator workspace</p><h1 className="mt-1 text-2xl font-semibold tracking-tight sm:text-3xl">Your teaching desk</h1><p className="mt-2 text-sm text-[var(--br-text-muted)]">Plan, capture, and finish your BrenUp work in one focused place.</p></div><div className="workspace-quick-actions flex w-full flex-wrap gap-2 sm:w-auto"><form action={createWorkspaceProject} className="workspace-quick-form flex min-w-0 flex-1 gap-2 sm:flex-none"><input name="title" required placeholder="New project name" className="field h-10 min-w-0 flex-1 sm:w-56 sm:flex-none" /><button className="inline-flex h-10 shrink-0 items-center gap-2 rounded-lg bg-[var(--br-action)] px-3 text-sm font-bold text-on-dark"><Plus size={15} /> Project</button></form><details className="workspace-new-task relative w-full sm:w-auto"><summary className="inline-flex min-h-10 w-full cursor-pointer list-none items-center justify-center gap-2 rounded-lg bg-[var(--br-brand)] px-3 text-sm font-bold text-on-dark sm:w-auto"><Plus size={15} /> New task</summary><form action={createWorkspaceTask} className="workspace-quick-form absolute right-0 top-12 z-20 grid w-[min(24rem,calc(100vw-2rem))] gap-2 rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><input name="title" required placeholder="Task name" className="field h-10 w-full" /><select name="project_id" aria-label="Assign task to project" className="field h-10 w-full"><option value="">Personal</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><div className="grid grid-cols-2 gap-2"><select name="priority" aria-label="Task priority" className="field h-10"><option value="NORMAL">Normal</option><option value="HIGH">High</option><option value="URGENT">Urgent</option><option value="LOW">Low</option></select><BrenDateTimeField name="due_at" label="Due date and time" /></div><textarea name="description" rows={2} placeholder="Details (optional)" className="field w-full" /><input name="related_url" type="url" placeholder="Related link (optional)" className="field w-full" /><select name="recurrence" aria-label="Task recurrence" className="field h-10 w-full"><option value="NONE">One time</option><option value="DAILY">Daily</option><option value="WEEKLY">Weekly</option><option value="MONTHLY">Monthly</option></select><button className="inline-flex h-10 items-center justify-center gap-2 rounded-lg bg-[var(--br-brand)] px-3 text-sm font-bold text-on-dark"><Plus size={15} /> Add task</button></form></details></div></header>
    <nav className="workspace-tabs flex gap-1 overflow-x-auto rounded-xl border border-[var(--br-border)] bg-surface p-1 shadow-sm">{orderedTabs.map((item) => <button type="button" draggable onDragStart={() => setDraggedTab(item)} onDragOver={(event) => event.preventDefault()} onDrop={() => reorderTabs(item)} onDragEnd={() => setDraggedTab(null)} key={item} onClick={() => setTab(item)} className={`whitespace-nowrap rounded-lg px-3 py-2 text-sm font-bold transition ${tab === item ? "bg-[var(--br-brand)] text-on-dark" : "text-[var(--br-text-muted)] hover:bg-[var(--br-surface-muted)]"}`}>{item}</button>)}</nav>
    {tab === "Overview" ? <Overview projects={projects} activeTasks={activeTasks} completedTasks={completedTasks} today={today} setTab={setTab} projectMap={projectMap} /> : null}
    {tab === "Tasks" ? <Tasks tasks={visibleTasks} projects={projects} projectMap={projectMap} query={query} setQuery={setQuery} filter={taskFilter} setFilter={setTaskFilter} projectId={taskProjectId} setProjectId={setTaskProjectId} sort={taskSort} setSort={setTaskSort} /> : null}
    {tab === "Board" ? <BoardView tasks={tasks} projects={projects} projectMap={projectMap} /> : null}
    {tab === "Projects" ? <Projects projects={projects} tasks={tasks} onOpenProject={setFocusedProjectId} /> : null}
    {tab === "Projects" ? <ProjectFocus projects={projects} tasks={tasks} notes={notes} resources={resources} selectedProjectId={focusedProjectId} onSelectProject={setFocusedProjectId} /> : null}
    {tab === "Calendar" ? <CalendarView tasks={tasks} projectMap={projectMap} /> : null}
    {tab === "Notes" ? <Notes notes={notes} projects={projects} /> : null}
    {tab === "Resources" ? <Resources resources={resources} projects={projects} /> : null}
  </main>;
}

function CalendarView({ tasks, projectMap }: { tasks: Task[]; projectMap: Map<string, string> }) {
  const [selectedDay, setSelectedDay] = useState(new Date().toDateString());
  const days = Array.from({ length: 14 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() + index); return date; });
  const scheduled = tasks.filter((task) => task.due_at).sort((a, b) => new Date(a.due_at as string).getTime() - new Date(b.due_at as string).getTime());
  const selectedTasks = scheduled.filter((task) => new Date(task.due_at as string).toDateString() === selectedDay);
  const selectedDate = days.find((day) => day.toDateString() === selectedDay);
  return <section className="overflow-hidden rounded-2xl border border-[var(--br-border)] bg-surface shadow-sm"><div className="border-b border-[var(--br-border)] px-4 py-4 sm:px-5"><div className="flex items-center gap-2"><span className="grid size-8 place-items-center rounded-lg bg-[var(--br-brand)]/10 text-[var(--br-brand)]"><CalendarDays size={16} /></span><h2 className="text-lg font-semibold">Calendar</h2></div><p className="mt-2 text-sm text-[var(--br-text-muted)]">Tap a date to see its tasks.</p><div className="mt-4 flex gap-2 overflow-x-auto pb-1">{days.map((day) => { const count = scheduled.filter((task) => new Date(task.due_at as string).toDateString() === day.toDateString()).length; const selected = day.toDateString() === selectedDay; return <button type="button" key={day.toISOString()} onClick={() => setSelectedDay(day.toDateString())} className={`min-w-16 rounded-xl border px-2 py-2 text-center ${selected ? "border-[var(--br-action)] bg-[var(--br-action)] text-on-dark" : "border-[var(--br-border)] bg-[var(--br-surface-muted)]"}`}><span className="block text-[10px] font-extrabold uppercase opacity-75">{day.toDateString() === new Date().toDateString() ? "Today" : day.toLocaleDateString(undefined, { weekday: "short" })}</span><span className="mt-1 block text-base font-bold">{day.getDate()}</span><span className={`mx-auto mt-1 grid size-4 place-items-center rounded-full text-[10px] font-bold ${selected ? "bg-white/20" : "bg-[var(--br-brand)]/10 text-[var(--br-brand)]"}`}>{count}</span></button>; })}</div></div><div className="px-4 py-4 sm:px-5"><h3 className="font-semibold">{selectedDate ? selectedDate.toLocaleDateString(undefined, { weekday: "long", month: "long", day: "numeric" }) : "Selected day"}</h3>{selectedTasks.length ? <div className="mt-3 space-y-2">{selectedTasks.map((task) => <div key={task.id} className="flex items-center justify-between gap-3 rounded-xl border border-[var(--br-border)] bg-[var(--br-surface-muted)]/45 px-3 py-3"><div className="min-w-0"><p className="truncate text-sm font-semibold">{task.title}</p><p className="mt-0.5 truncate text-xs text-[var(--br-text-muted)]">{task.project_id ? projectMap.get(task.project_id) : "Personal"} · {new Date(task.due_at as string).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })}</p></div><span className={`size-2 shrink-0 rounded-full ${task.status === "COMPLETED" ? "bg-[var(--br-success)]" : "bg-[var(--br-action)]"}`} /></div>)}</div> : <p className="mt-2 text-sm text-[var(--br-text-muted)]">Nothing scheduled for this day.</p>}</div></section>;
}

function LegacyCalendarView({ tasks, projectMap }: { tasks: Task[]; projectMap: Map<string, string> }) {
  const days = Array.from({ length: 14 }, (_, index) => { const date = new Date(); date.setHours(0, 0, 0, 0); date.setDate(date.getDate() + index); return date; });
  const scheduled = tasks.filter((task) => task.due_at).sort((a, b) => new Date(a.due_at as string).getTime() - new Date(b.due_at as string).getTime());
  const withoutDate = tasks.filter((task) => !task.due_at && task.status !== "COMPLETED");
  const today = days[0].toDateString();
  const dueSoon = scheduled.filter((task) => new Date(task.due_at as string).getTime() < days[7].getTime()).length;
  return <section className="overflow-hidden rounded-2xl border border-[var(--br-border)] bg-surface shadow-sm"><div className="border-b border-[var(--br-border)] px-4 py-4 sm:px-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className="grid size-8 place-items-center rounded-lg bg-[var(--br-brand)]/10 text-[var(--br-brand)]"><CalendarDays size={16} /></span><h2 className="text-lg font-semibold">Calendar</h2></div><p className="mt-2 text-sm text-[var(--br-text-muted)]">A clear view of what is coming next.</p></div><div className="flex gap-2 text-xs font-bold"><span className="rounded-full bg-[var(--br-brand)]/10 px-2.5 py-1.5 text-[var(--br-brand)]">{scheduled.length} scheduled</span><span className="rounded-full bg-[var(--br-action)]/10 px-2.5 py-1.5 text-[var(--br-action)]">{dueSoon} this week</span></div></div><div className="mt-4 flex gap-2 overflow-x-auto pb-1">{days.map((day) => { const isToday = day.toDateString() === today; const count = scheduled.filter((task) => new Date(task.due_at as string).toDateString() === day.toDateString()).length; return <div key={day.toISOString()} className={`min-w-16 rounded-xl border px-2 py-2 text-center ${isToday ? "border-[var(--br-action)] bg-[var(--br-action)] text-on-dark shadow-sm" : "border-[var(--br-border)] bg-[var(--br-surface-muted)]"}`}><p className="text-[10px] font-extrabold uppercase tracking-wide opacity-75">{isToday ? "Today" : day.toLocaleDateString(undefined, { weekday: "short" })}</p><p className="mt-1 text-base font-bold">{day.getDate()}</p><span className={`mx-auto mt-1 grid size-4 place-items-center rounded-full text-[10px] font-bold ${isToday ? "bg-white/20" : "bg-[var(--br-brand)]/10 text-[var(--br-brand)]"}`}>{count}</span></div>; })}</div></div><div className="divide-y divide-[var(--br-border)]">{days.map((day) => { const dayTasks = scheduled.filter((task) => new Date(task.due_at as string).toDateString() === day.toDateString()); if (!dayTasks.length) return null; const isToday = day.toDateString() === today; return <div key={day.toISOString()} className="flex gap-3 px-4 py-4 sm:px-5"><div className="w-16 shrink-0"><p className={`text-xs font-extrabold uppercase ${isToday ? "text-[var(--br-action)]" : "text-[var(--br-text-muted)]"}`}>{isToday ? "Today" : day.toLocaleDateString(undefined, { weekday: "short" })}</p><p className="mt-1 text-sm font-semibold text-ink">{day.toLocaleDateString(undefined, { month: "short", day: "numeric" })}</p></div><div className="min-w-0 flex-1 space-y-2">{dayTasks.map((task) => <div key={task.id} className={`flex min-w-0 items-center justify-between gap-3 rounded-xl border px-3 py-2.5 ${task.status === "COMPLETED" ? "border-[var(--br-success)]/25 bg-[var(--br-success)]/5" : "border-[var(--br-border)] bg-[var(--br-surface-muted)]/45"}`}><div className="min-w-0"><p className={`truncate text-sm font-semibold ${task.status === "COMPLETED" ? "text-[var(--br-text-muted)] line-through" : "text-ink"}`}>{task.title}</p><p className="mt-0.5 truncate text-xs text-[var(--br-text-muted)]">{task.project_id ? projectMap.get(task.project_id) : "Personal"} · {new Date(task.due_at as string).toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })}</p></div><span className={`size-2 shrink-0 rounded-full ${task.status === "COMPLETED" ? "bg-[var(--br-success)]" : "bg-[var(--br-action)]"}`} /></div>)}</div></div>; })}{!scheduled.length ? <div className="px-5 py-12 text-center"><CalendarDays className="mx-auto text-[var(--br-text-muted)]" /><p className="mt-3 font-semibold">Your calendar is open</p><p className="mt-1 text-sm text-[var(--br-text-muted)]">Add a due date to a task and it will appear here.</p></div> : null}</div>{withoutDate.length ? <div className="border-t border-[var(--br-border)] bg-[var(--br-surface-muted)]/30 px-4 py-4 sm:px-5"><h3 className="font-semibold">Needs a date <span className="ml-1 text-xs font-bold text-[var(--br-text-muted)]">{withoutDate.length}</span></h3><div className="mt-3 grid gap-2">{withoutDate.map((task) => <TaskRow key={task.id} task={task} projectMap={projectMap} />)}</div></div> : null}</section>;
}

function BoardView({ tasks, projects, projectMap }: { tasks: Task[]; projects: Project[]; projectMap: Map<string, string> }) {
  const router = useRouter();
  const [dragging, setDragging] = useState<string | null>(null);
  const [allBoardTasks, setBoardTasks] = useState(tasks);
  const [boardFilter, setBoardFilter] = useState<"ALL" | "TODAY" | "TOMORROW">("ALL");
  useEffect(() => setBoardTasks(tasks), [tasks]);
  const columns = [{ status: "TODO", label: "To do", tone: "var(--br-brand)" }, { status: "IN_PROGRESS", label: "In progress", tone: "var(--br-action)" }, { status: "WAITING", label: "Waiting", tone: "var(--br-info)" }, { status: "COMPLETED", label: "Completed", tone: "var(--br-success)" }];
  async function moveTask(id: string, status: string) { const previous = allBoardTasks; setBoardTasks((current) => current.map((task) => task.id === id ? { ...task, status } : task)); const form = new FormData(); form.set("id", id); form.set("status", status); try { await updateWorkspaceTask(form); router.refresh(); } catch { setBoardTasks(previous); } }
  function beginDrag(event: React.DragEvent<HTMLDivElement>, task: Task) { if ((event.target as HTMLElement).closest("button,a,input,textarea,select,summary,form")) { event.preventDefault(); return; } const preview = document.createElement("div"); preview.textContent = task.title; preview.style.cssText = "position:fixed;top:-10000px;left:-10000px;width:280px;padding:14px;border:1px solid #ddd;border-radius:12px;background:#fff;color:#26254f;font:600 14px system-ui;box-shadow:0 10px 30px rgba(0,0,0,.12)"; document.body.appendChild(preview); event.dataTransfer.setDragImage(preview, 24, 24); event.dataTransfer.setData("text/task-id", task.id); event.dataTransfer.effectAllowed = "move"; setDragging(task.id); window.setTimeout(() => preview.remove(), 0); }
  const boardTasks = allBoardTasks.filter((task) => { if (boardFilter === "ALL") return true; if (!task.due_at) return false; const start = new Date(); start.setHours(0, 0, 0, 0); const tomorrow = new Date(start); tomorrow.setDate(tomorrow.getDate() + 1); const end = new Date(tomorrow); if (boardFilter === "TOMORROW") end.setDate(end.getDate() + 1); return boardFilter === "TODAY" ? new Date(task.due_at) >= start && new Date(task.due_at) < tomorrow : new Date(task.due_at) >= tomorrow && new Date(task.due_at) < end; });
  return <section className="select-none rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-semibold">Task board</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Drag a task card between stages.</p></div><div className="flex items-center gap-2"><select value={boardFilter} onChange={(event) => setBoardFilter(event.target.value as typeof boardFilter)} className="field h-8 w-24 rounded-full px-2 py-0 text-xs font-bold"><option value="ALL">All tasks</option><option value="TODAY">Today</option><option value="TOMORROW">Tomorrow</option></select><span className="rounded-full bg-[var(--br-surface-muted)] px-2.5 py-1.5 text-xs font-bold text-[var(--br-text-muted)]">{boardTasks.length} total</span></div></div><div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-4">{columns.map((column) => { const columnTasks = boardTasks.filter((task) => task.status === column.status); return <div key={column.status} onDragOver={(event) => { event.preventDefault(); event.dataTransfer.dropEffect = "move"; }} onDrop={(event) => { event.preventDefault(); const id = dragging || event.dataTransfer.getData("text/task-id"); if (id) void moveTask(id, column.status); setDragging(null); }} className={`min-w-0 rounded-xl border bg-[var(--br-surface-muted)]/35 p-3 transition ${dragging ? "border-dashed border-[var(--br-brand)]/50" : "border-[var(--br-border)]"}`}><div className="flex items-center justify-between gap-2"><div className="flex items-center gap-2"><span className="size-2 rounded-full" style={{ backgroundColor: column.tone }} /><h3 className="text-sm font-bold">{column.label}</h3>{column.status === "TODO" ? <details className="relative"><summary className="grid size-6 cursor-pointer list-none place-items-center rounded-md bg-[var(--br-brand)]/10 text-[var(--br-brand)]" aria-label="Add task to To do"><Plus size={14} /></summary><form action={createWorkspaceTask} className="absolute left-0 top-8 z-30 grid w-64 gap-2 rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><input name="title" required placeholder="Task name" className="field h-9" /><select name="project_id" className="field h-9"><option value="">Personal</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><select name="priority" className="field h-9"><option value="NORMAL">Normal</option><option value="LOW">Low</option><option value="HIGH">High</option><option value="URGENT">Urgent</option></select><BrenDateTimeField name="due_at" label="Due date and time" /><button className="rounded-lg bg-[var(--br-brand)] px-3 py-2 text-xs font-bold text-on-dark">Add to To do</button></form></details> : null}</div><span className="text-xs font-bold text-[var(--br-text-muted)]">{columnTasks.length}</span></div><div className="mt-3 space-y-2">{columnTasks.map((task) => <div key={task.id} draggable onDragStart={(event) => beginDrag(event, task)} onDragEnd={() => setDragging(null)} className="min-w-0 cursor-grab active:cursor-grabbing"><TaskRow task={task} projectMap={projectMap} showDelete /></div>)}{!columnTasks.length ? <p className="rounded-lg border border-dashed border-[var(--br-border)] px-3 py-5 text-center text-xs text-[var(--br-text-muted)]">Drop tasks here</p> : null}</div></div>; })}</div></section>;
}

function LegacyBoardView({ tasks, projectMap }: { tasks: Task[]; projectMap: Map<string, string> }) {
  const columns = [{ status: "TODO", label: "To do", tone: "var(--br-brand)" }, { status: "IN_PROGRESS", label: "In progress", tone: "var(--br-action)" }, { status: "WAITING", label: "Waiting", tone: "var(--br-info)" }, { status: "COMPLETED", label: "Completed", tone: "var(--br-success)" }];
  return <section className="rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><h2 className="text-lg font-semibold">Task board</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">See the shape of your work at a glance.</p></div><span className="rounded-full bg-[var(--br-surface-muted)] px-2.5 py-1.5 text-xs font-bold text-[var(--br-text-muted)]">{tasks.length} total</span></div><div className="mt-5 grid gap-3 overflow-x-auto md:grid-cols-2 xl:grid-cols-4">{columns.map((column) => { const columnTasks = tasks.filter((task) => task.status === column.status); return <div key={column.status} className="min-w-0 rounded-xl border border-[var(--br-border)] bg-[var(--br-surface-muted)]/35 p-3"><div className="flex items-center justify-between gap-2"><div className="flex items-center gap-2"><span className="size-2 rounded-full" style={{ backgroundColor: column.tone }} /><h3 className="text-sm font-bold">{column.label}</h3></div><span className="text-xs font-bold text-[var(--br-text-muted)]">{columnTasks.length}</span></div><div className="mt-3 space-y-2">{columnTasks.map((task) => <TaskRow key={task.id} task={task} projectMap={projectMap} showDelete />)}{!columnTasks.length ? <p className="rounded-lg border border-dashed border-[var(--br-border)] px-3 py-5 text-center text-xs text-[var(--br-text-muted)]">No tasks here</p> : null}</div></div>; })}</div></section>;
}

function ReadMoreText({ text }: { text: string }) {
  const [open, setOpen] = useState(false);
  if (!text) return <p className="mt-2 text-sm text-[var(--br-text-muted)]">Empty note</p>;
  return <div className="mt-2"><p className={`whitespace-pre-wrap text-sm leading-6 text-[var(--br-text-muted)] ${open ? "" : "line-clamp-1"}`}>{text}</p>{text.length > 90 ? <button type="button" onClick={() => setOpen((value) => !value)} className="mt-1 text-xs font-bold text-[var(--br-brand)]">{open ? "Read less" : "Read more"}</button> : null}</div>;
}

function ProjectFocus({ projects, tasks, notes, resources, selectedProjectId, onSelectProject }: { projects: Project[]; tasks: Task[]; notes: Note[]; resources: Resource[]; selectedProjectId: string | null; onSelectProject: (id: string | null) => void }) {
  const [projectId, setProjectId] = useState(selectedProjectId ?? projects[0]?.id ?? "");
  useEffect(() => { if (selectedProjectId) setProjectId(selectedProjectId); }, [selectedProjectId]);
  const project = projects.find((item) => item.id === projectId);
  const projectTasks = tasks.filter((task) => task.project_id === projectId);
  const projectNotes = notes.filter((note) => note.project_id === projectId);
  const projectResources = resources.filter((resource) => resource.project_id === projectId);
  if (!projects.length) return null;
  return <section className="mt-5 rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--br-brand)]">Project focus</p><h2 className="mt-1 text-lg font-semibold">Everything for one project</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Keep the work, notes, and references together.</p></div><select value={projectId} onChange={(event) => { setProjectId(event.target.value); onSelectProject(event.target.value); }} className="field h-10 w-full sm:w-64"><option value="" disabled>Choose a project</option>{projects.map((item) => <option key={item.id} value={item.id}>{item.title}</option>)}</select></div>{project ? <><div className="mt-4 flex flex-wrap items-center gap-2 border-y border-[var(--br-border)] py-3"><span className="rounded-full bg-[var(--br-brand)]/10 px-2.5 py-1 text-xs font-bold text-[var(--br-brand)]">{project.status}</span><span className="text-sm font-semibold text-ink">{project.title}</span><span className="text-xs text-[var(--br-text-muted)]">{project.due_at ? `Due ${new Date(project.due_at).toLocaleDateString()}` : "No deadline"}</span></div><div className="mt-4 grid gap-3 sm:grid-cols-3"><FocusStat label="Tasks" value={projectTasks.length} /><FocusStat label="Notes" value={projectNotes.length} /><FocusStat label="Resources" value={projectResources.length} /></div><div className="mt-4 grid gap-4 lg:grid-cols-3"><FocusList title="Tasks" empty="No tasks linked yet" items={projectTasks.map((task) => ({ id: task.id, title: (task.status === "COMPLETED" ? "✓ " : "") + task.title, detail: task.description || "No details added." }))} action="task" projectId={project.id} /><FocusList title="Notes" empty="No notes linked yet" items={projectNotes.map((note) => ({ id: note.id, title: note.title, detail: note.body }))} action="note" projectId={project.id} /><FocusList title="Resources" empty="No resources linked yet" items={projectResources.map((resource) => ({ id: resource.id, title: resource.title, detail: resource.value }))} action="resource" projectId={project.id} /></div></> : null}</section>;
}

function FocusStat({ label, value }: { label: string; value: number }) { return <div className="rounded-xl border border-[var(--br-border)] bg-[var(--br-surface-muted)]/35 px-3 py-3"><p className="text-xl font-bold text-ink">{value}</p><p className="mt-1 text-xs font-bold uppercase tracking-wide text-[var(--br-text-muted)]">{label}</p></div>; }
function FocusList({ title, empty, items, action, projectId }: { title: string; empty: string; items: { id: string; title: string; detail: string }[]; action: "task" | "note" | "resource"; projectId: string }) { const [open, setOpen] = useState(false); const [selected, setSelected] = useState<{ title: string; detail: string } | null>(null); const actionLabel = action === "task" ? "task" : action === "note" ? "note" : "resource"; return <div className="min-w-0"><div className="flex items-center justify-between gap-2"><h3 className="text-sm font-bold">{title}</h3><button type="button" onClick={() => setOpen((value) => !value)} className="grid size-7 place-items-center rounded-lg bg-[var(--br-brand)]/10 text-[var(--br-brand)]" aria-label={`Add ${actionLabel}`}><Plus size={15} /></button></div>{open ? <form action={action === "task" ? createWorkspaceTask : action === "note" ? createWorkspaceNote : createWorkspaceResource} className="mt-2 space-y-2 rounded-xl border border-[var(--br-border)] bg-[var(--br-surface-muted)] p-2"><input type="hidden" name="project_id" value={projectId} /><input name="title" required placeholder={`New ${actionLabel}`} className="field" />{action === "note" ? <textarea name="body" rows={3} placeholder="Note" className="field" /> : action === "resource" ? <textarea name="value" required rows={2} placeholder="URL or code" className="field" /> : null}<button className="w-full rounded-lg bg-[var(--br-brand)] px-3 py-2 text-sm font-bold text-on-dark">Add {actionLabel}</button></form> : null}<div className="mt-2 space-y-1.5">{items.slice(0, 5).map((item) => <button type="button" key={item.id} onClick={() => setSelected(item)} className="block w-full truncate rounded-lg border border-[var(--br-border)] px-3 py-2 text-left text-sm text-ink hover:border-[var(--br-brand)]/40 hover:bg-[var(--br-brand)]/[0.03]">{item.title}</button>)}{!items.length ? <p className="rounded-lg border border-dashed border-[var(--br-border)] px-3 py-3 text-xs text-[var(--br-text-muted)]">{empty}</p> : null}</div>{selected ? <div className="mt-2 rounded-xl border border-[var(--br-brand)]/20 bg-[var(--br-brand)]/[0.04] p-3"><div className="flex items-start justify-between gap-2"><h4 className="text-sm font-bold">{selected.title}</h4><button type="button" onClick={() => setSelected(null)} className="text-xs font-bold text-[var(--br-brand)]">Close</button></div><p className="mt-2 whitespace-pre-wrap break-words text-sm leading-6 text-[var(--br-text-muted)]">{selected.detail}</p></div> : null}</div>; }
function Overview({ projects, activeTasks, completedTasks, today, setTab, projectMap }: { projects: Project[]; activeTasks: Task[]; completedTasks: number; today: string; setTab: (tab: (typeof tabs)[number]) => void; projectMap: Map<string, string> }) {
  return <><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={ListChecks} label="Open tasks" value={activeTasks.length} tone="purple" /><Metric icon={CheckCircle2} label="Completed" value={completedTasks} tone="green" /><Metric icon={FolderKanban} label="Active projects" value={projects.filter((project) => project.status === "ACTIVE").length} tone="orange" /><Metric icon={CalendarDays} label="Due today" value={activeTasks.filter((task) => task.due_at && new Date(task.due_at).toDateString() === today).length} tone="blue" /></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1.3fr)_minmax(300px,1fr)]"><AttentionCard tasks={activeTasks} projectMap={projectMap} setTab={setTab} /><section className="rounded-2xl border border-[var(--br-border)] bg-surface p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">Recent projects</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Keep your teaching work moving.</p></div><button type="button" onClick={() => setTab("Projects")} className="text-sm font-bold text-[var(--br-brand)]">View all</button></div><div className="mt-4 space-y-3">{projects.slice(0, 5).map((project) => <article key={project.id} className="rounded-xl border border-[var(--br-border)] p-3"><div className="flex items-center justify-between gap-3"><p className="min-w-0 truncate font-semibold">{project.title}</p><span className="rounded-full bg-[var(--br-brand)]/10 px-2 py-1 text-[10px] font-bold text-[var(--br-brand)]">{project.status}</span></div></article>)}{!projects.length ? <Empty icon={FolderKanban} title="No projects yet" detail="Create your first teaching project above." /> : null}</div></section></div></>;
}

function AttentionCard({ tasks, projectMap, setTab }: { tasks: Task[]; projectMap: Map<string, string>; setTab: (tab: (typeof tabs)[number]) => void }) {
  const [filter, setFilter] = useState("TODAY");
  const now = new Date(); const start = new Date(now); start.setHours(0, 0, 0, 0); const tomorrow = new Date(start); tomorrow.setDate(tomorrow.getDate() + 1); const week = new Date(start); week.setDate(week.getDate() + 7); const month = new Date(start); month.setMonth(month.getMonth() + 1);
  const visible = tasks.filter((task) => { if (!task.due_at) return filter === "TODAY" ? false : filter === "OVERDUE" ? false : true; const due = new Date(task.due_at); if (filter === "OVERDUE") return due < start; if (filter === "TODAY") return due >= start && due < tomorrow; if (filter === "TOMORROW") return due >= tomorrow && due < new Date(tomorrow.getTime() + 86400000); if (filter === "WEEK") return due >= start && due < week; return due >= start && due < month; }).slice(0, 6);
  return <section className="rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-start justify-between gap-3"><div><h2 className="text-lg font-semibold">What needs attention</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Your next unfinished tasks.</p></div><div className="flex items-center gap-2"><select value={filter} onChange={(event) => setFilter(event.target.value)} className="field h-9 w-32 py-1 text-xs sm:w-36"><option value="TODAY">Today</option><option value="TOMORROW">Tomorrow</option><option value="WEEK">This week</option><option value="MONTH">This month</option><option value="OVERDUE">Overdue</option></select><button type="button" onClick={() => setTab("Tasks")} className="text-sm font-bold text-[var(--br-brand)]">View all</button></div></div><div className="mt-3 space-y-2">{visible.map((task) => <TaskRow key={task.id} task={task} projectMap={projectMap} />)}{!visible.length ? <p className="rounded-xl bg-[var(--br-surface-muted)] px-3 py-4 text-sm text-[var(--br-text-muted)]">Nothing scheduled for this period.</p> : null}<details className="relative"><summary className="flex w-full cursor-pointer list-none items-center gap-3 rounded-xl border border-dashed border-[var(--br-brand)]/40 px-3 py-3 text-left text-sm font-bold text-[var(--br-brand)]"><Plus size={17} /> New task</summary><form action={createWorkspaceTask} className="absolute bottom-12 left-0 z-20 grid w-[min(28rem,calc(100vw-2rem))] gap-2 rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><input name="title" required placeholder="Task title" className="field" /><select name="project_id" className="field"><option value="">Personal</option>{Array.from(projectMap.entries()).map(([id, title]) => <option key={id} value={id}>{title}</option>)}</select><textarea name="description" rows={2} placeholder="Details (optional)" className="field" /><div className="grid grid-cols-2 gap-2"><select name="priority" className="field"><option value="NORMAL">Normal</option><option value="LOW">Low</option><option value="HIGH">High</option><option value="URGENT">Urgent</option></select><BrenDateTimeField name="due_at" label="Due date and time" /></div><select name="recurrence" className="field"><option value="NONE">One time</option><option value="DAILY">Daily</option><option value="WEEKLY">Weekly</option><option value="MONTHLY">Monthly</option></select><input name="related_url" type="url" placeholder="Related link (optional)" className="field" /><button className="rounded-lg bg-[var(--br-brand)] px-3 py-2 text-sm font-bold text-on-dark">Create task</button></form></details></div></section>;
}

function LegacyOverview({ projects, activeTasks, completedTasks, today, setTab, projectMap }: { projects: Project[]; activeTasks: Task[]; completedTasks: number; today: string; setTab: (tab: (typeof tabs)[number]) => void; projectMap: Map<string, string> }) {
  return <><section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={ListChecks} label="Open tasks" value={activeTasks.length} tone="purple" /><Metric icon={CheckCircle2} label="Completed" value={completedTasks} tone="green" /><Metric icon={FolderKanban} label="Active projects" value={projects.filter((project) => project.status === "ACTIVE").length} tone="orange" /><Metric icon={CalendarDays} label="Due today" value={activeTasks.filter((task) => task.due_at && new Date(task.due_at).toDateString() === today).length} tone="blue" /></section><div className="grid gap-5 xl:grid-cols-[minmax(0,1.3fr)_minmax(300px,1fr)]"><section className="rounded-2xl border border-[var(--br-border)] bg-surface p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">What needs attention</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Your next unfinished tasks.</p></div><button type="button" onClick={() => setTab("Tasks")} className="text-sm font-bold text-[var(--br-brand)]">View all</button></div><div className="mt-4 space-y-2">{activeTasks.slice(0, 6).map((task) => <TaskRow key={task.id} task={task} projectMap={projectMap} />)}{!activeTasks.length ? <Empty icon={CheckCircle2} title="Nothing needs attention" detail="You are all caught up." /> : null}</div></section><section className="rounded-2xl border border-[var(--br-border)] bg-surface p-5 shadow-sm"><div className="flex items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">Recent projects</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Keep your teaching work moving.</p></div><button type="button" onClick={() => setTab("Projects")} className="text-sm font-bold text-[var(--br-brand)]">View all</button></div><div className="mt-4 space-y-3">{projects.slice(0, 5).map((project) => <article key={project.id} className="rounded-xl border border-[var(--br-border)] p-3"><div className="flex items-center justify-between gap-3"><p className="min-w-0 truncate font-semibold">{project.title}</p><span className="rounded-full bg-[var(--br-brand)]/10 px-2 py-1 text-[10px] font-bold text-[var(--br-brand)]">{project.status}</span></div><div className="mt-2 h-1.5 rounded-full bg-[var(--br-surface-muted)]"><div className="h-full w-1/3 rounded-full bg-[var(--br-action)]" /></div></article>)}{!projects.length ? <Empty icon={FolderKanban} title="No projects yet" detail="Create your first teaching project above." /> : null}</div></section></div></>;
}

function TodaySummary({ tasks, projectMap }: { tasks: Task[]; projectMap: Map<string, string> }) {
  const now = new Date();
  const start = new Date(now); start.setHours(0, 0, 0, 0);
  const tomorrow = new Date(start); tomorrow.setDate(tomorrow.getDate() + 1);
  const overdue = tasks.filter((task) => task.status !== "COMPLETED" && task.due_at && new Date(task.due_at) < start);
  const todayTasks = tasks.filter((task) => task.status !== "COMPLETED" && task.due_at && new Date(task.due_at) >= start && new Date(task.due_at) < tomorrow);
  const upcoming = tasks.filter((task) => task.status !== "COMPLETED" && task.due_at && new Date(task.due_at) >= tomorrow).sort((a, b) => new Date(a.due_at as string).getTime() - new Date(b.due_at as string).getTime()).slice(0, 4);
  const items = [...overdue.slice(0, 3).map((task) => ({ task, label: "Overdue", tone: "text-[var(--br-danger)]" })), ...todayTasks.slice(0, 3).map((task) => ({ task, label: "Today", tone: "text-[var(--br-action)]" })), ...upcoming.map((task) => ({ task, label: new Date(task.due_at as string).toLocaleDateString(undefined, { month: "short", day: "numeric" }), tone: "text-[var(--br-brand)]" }))];
  return <section className="rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm sm:p-5"><div className="flex flex-wrap items-end justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.14em] text-[var(--br-brand)]">At a glance</p><h2 className="mt-1 text-lg font-semibold">Today’s focus</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">The work that deserves your attention first.</p></div><div className="flex gap-2 text-xs font-bold"><span className="rounded-full bg-[var(--br-danger)]/10 px-2.5 py-1.5 text-[var(--br-danger)]">{overdue.length} overdue</span><span className="rounded-full bg-[var(--br-action)]/10 px-2.5 py-1.5 text-[var(--br-action)]">{todayTasks.length} today</span></div></div><div className="mt-4 divide-y divide-[var(--br-border)]">{items.map(({ task, label, tone }) => <div key={task.id} className="flex min-w-0 items-center gap-3 py-3 first:pt-0 last:pb-0"><span className={`w-14 shrink-0 text-[10px] font-extrabold uppercase ${tone}`}>{label}</span><div className="min-w-0 flex-1"><p className="truncate text-sm font-semibold">{task.title}</p><p className="mt-0.5 truncate text-xs text-[var(--br-text-muted)]">{task.project_id ? projectMap.get(task.project_id) : "Personal"}</p></div><span className={`size-2 shrink-0 rounded-full ${task.priority === "URGENT" ? "bg-[var(--br-danger)]" : task.priority === "HIGH" ? "bg-[var(--br-action)]" : "bg-[var(--br-brand)]/40"}`} /></div>)}{!items.length ? <p className="py-3 text-sm text-[var(--br-text-muted)]">No urgent work on your horizon.</p> : null}</div></section>;
}

function CreateTaskCard({ projects }: { projects: Project[] }) { return <section className="rounded-2xl border border-dashed border-[var(--br-brand)]/40 bg-[var(--br-brand)]/[0.03] p-4 sm:p-5"><div className="flex items-center gap-2"><span className="grid size-8 place-items-center rounded-lg bg-[var(--br-brand)]/10 text-[var(--br-brand)]"><Plus size={16} /></span><div><h2 className="font-semibold">Create task</h2><p className="text-xs text-[var(--br-text-muted)]">Add a task without leaving My Tasks.</p></div></div><form action={createWorkspaceTask} className="mt-4 grid gap-2 sm:grid-cols-2 lg:grid-cols-4"><input name="title" required placeholder="Task title" className="field sm:col-span-2" /><select name="project_id" className="field"><option value="">Personal</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><select name="priority" className="field"><option value="NORMAL">Normal priority</option><option value="LOW">Low priority</option><option value="HIGH">High priority</option><option value="URGENT">Urgent priority</option></select><select name="status" className="field"><option value="TODO">To do</option><option value="IN_PROGRESS">In progress</option><option value="WAITING">Waiting</option></select><BrenDateTimeField name="due_at" label="Due date and time" /><select name="recurrence" className="field"><option value="NONE">One time</option><option value="DAILY">Daily</option><option value="WEEKLY">Weekly</option><option value="MONTHLY">Monthly</option></select><input name="label" placeholder="Label (optional)" className="field" /><input name="related_url" type="url" placeholder="Related link (optional)" className="field sm:col-span-2" /><button className="inline-flex min-h-11 items-center justify-center gap-2 rounded-lg bg-[var(--br-brand)] px-4 py-2.5 text-sm font-bold text-on-dark"><Plus size={15} /> Create task</button></form></section>;}
function Tasks({ tasks, projects, projectMap, query, setQuery, filter, setFilter, projectId, setProjectId, sort, setSort }: { tasks: Task[]; projects: Project[]; projectMap: Map<string, string>; query: string; setQuery: (value: string) => void; filter: "ALL" | "OPEN" | "TODAY" | "HIGH"; setFilter: (value: "ALL" | "OPEN" | "TODAY" | "HIGH") => void; projectId: string; setProjectId: (value: string) => void; sort: "RECENT" | "DUE"; setSort: (value: "RECENT" | "DUE") => void }) {
  return <section className="rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm sm:p-5"><CreateTaskCard projects={projects} /><div className="mt-5 flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-lg font-semibold">My tasks</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Small next steps make big lessons easier.</p></div><div className="flex w-full flex-wrap gap-2 sm:w-auto"><div className="relative min-w-0 flex-1 sm:flex-none"><Search size={15} className="absolute left-3 top-3 text-[var(--br-text-muted)]" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search tasks" className="field h-10 w-full pl-9 sm:w-48" /></div><select value={filter} onChange={(event) => setFilter(event.target.value as typeof filter)} className="field h-10 w-full sm:w-auto"><option value="ALL">All tasks</option><option value="OPEN">Open only</option><option value="TODAY">Due today</option><option value="HIGH">High priority</option></select></div></div><div className="mt-3 flex flex-wrap gap-2 border-t border-[var(--br-border)] pt-3"><select value={projectId} onChange={(event) => setProjectId(event.target.value)} className="field h-9 min-w-0 flex-1 text-xs sm:flex-none"><option value="ALL">All projects</option><option value="PERSONAL">Personal tasks</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><select value={sort} onChange={(event) => setSort(event.target.value as typeof sort)} className="field h-9 min-w-0 flex-1 text-xs sm:flex-none"><option value="RECENT">Recent first</option><option value="DUE">Due date first</option></select><span className="self-center text-xs font-semibold text-[var(--br-text-muted)]">{tasks.length} shown</span></div><div className="mt-4 space-y-2">{tasks.map((task) => <TaskRow key={task.id} task={task} projectMap={projectMap} showDelete />)}{!tasks.length ? <Empty icon={ListChecks} title="No tasks found" detail="Try another filter or add a quick task above." /> : null}</div></section>;
}

function TaskRow({ task, projectMap, showDelete = false }: { task: Task; projectMap: Map<string, string>; showDelete?: boolean }) {
  const completed = task.status === "COMPLETED";
  return <article className={`flex items-start gap-3 rounded-xl border p-3 transition ${completed ? "border-[var(--br-success)]/20 bg-[var(--br-success)]/5" : "border-[var(--br-border)] hover:border-[var(--br-brand)]/30"}`}><form action={toggleWorkspaceTask}><input type="hidden" name="id" value={task.id} /><input type="hidden" name="completed" value={String(completed)} /><button className={`mt-0.5 grid size-5 place-items-center rounded-full border ${completed ? "border-[var(--br-success)] bg-[var(--br-success)] text-on-dark" : "border-[var(--br-brand)]/40"}`} aria-label={completed ? "Mark task open" : "Complete task"}>{completed ? <Check size={13} /> : null}</button></form><div className="min-w-0 flex-1"><p className={`break-words text-sm font-semibold ${completed ? "text-[var(--br-text-muted)] line-through" : "text-ink"}`}>{task.title}</p><div className="mt-1 flex flex-wrap items-center gap-2 text-xs text-[var(--br-text-muted)]"><span>{task.project_id ? projectMap.get(task.project_id) : "Personal"}</span>{task.label ? <span className="rounded-full bg-[var(--br-brand)]/10 px-2 py-0.5 text-[var(--br-brand)]">{task.label}</span> : null}{task.due_at ? <span>{new Date(task.due_at).toLocaleDateString()}</span> : null}{task.related_url ? <a href={task.related_url} target="_blank" rel="noreferrer" className="inline-flex items-center gap-1 font-bold text-[var(--br-brand)]"><ExternalLink size={12} /> Open link</a> : null}</div></div><details className="relative shrink-0"><summary className="grid size-8 cursor-pointer list-none place-items-center rounded-lg text-[var(--br-text-muted)] hover:bg-[var(--br-surface-muted)]"><Pencil size={14} /><span className="sr-only">Edit task</span></summary><form action={updateWorkspaceTask} className="absolute right-0 z-10 mt-2 w-72 space-y-2 rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><input type="hidden" name="id" value={task.id} /><input name="title" required defaultValue={task.title} className="field" /><textarea name="description" defaultValue={task.description ?? ""} rows={2} placeholder="Details" className="field" /><select name="project_id" defaultValue={task.project_id ?? ""} className="field"><option value="">Personal</option>{Array.from(projectMap.entries()).map(([id, title]) => <option key={id} value={id}>{title}</option>)}</select><div className="grid grid-cols-2 gap-2"><select name="status" defaultValue={task.status} className="field"><option value="TODO">To do</option><option value="IN_PROGRESS">In progress</option><option value="WAITING">Waiting</option><option value="COMPLETED">Completed</option></select><select name="priority" defaultValue={task.priority} className="field"><option value="LOW">Low</option><option value="NORMAL">Normal</option><option value="HIGH">High</option><option value="URGENT">Urgent</option></select></div><input name="label" defaultValue={task.label ?? ""} placeholder="Label" className="field" /><BrenDateTimeField name="due_at" defaultValue={dateInputValue(task.due_at)} label="Due date and time" /><select name="recurrence" defaultValue={task.recurrence} className="field"><option value="NONE">Does not repeat</option><option value="DAILY">Every day</option><option value="WEEKLY">Every week</option><option value="MONTHLY">Every month</option></select><input name="related_url" type="url" defaultValue={task.related_url ?? ""} placeholder="Related link" className="field" /><button className="w-full rounded-lg bg-[var(--br-brand)] px-3 py-2 text-sm font-bold text-on-dark">Save changes</button></form></details>{showDelete ? <form action={deleteWorkspaceTask}><input type="hidden" name="id" value={task.id} /><button className="grid size-8 shrink-0 place-items-center rounded-lg text-[var(--br-text-muted)] hover:bg-[var(--br-danger)]/10 hover:text-[var(--br-danger)]" title="Delete task" aria-label="Delete task"><Trash2 size={15} /></button></form> : null}</article>;
}

function Projects({ projects, tasks, onOpenProject }: { projects: Project[]; tasks: Task[]; onOpenProject: (id: string) => void }) { return <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{projects.map((project) => { const projectTasks = tasks.filter((task) => task.project_id === project.id); const completed = projectTasks.filter((task) => task.status === "COMPLETED").length; const progress = projectTasks.length ? Math.round((completed / projectTasks.length) * 100) : 0; return <article key={project.id} className="rounded-2xl border border-[var(--br-border)] bg-surface p-5 shadow-sm"><div className="flex items-start justify-between gap-3"><span className="grid size-10 place-items-center rounded-xl bg-[var(--br-brand)]/10 text-[var(--br-brand)]"><FolderKanban size={19} /></span><div className="flex items-center gap-1"><span className="rounded-full bg-[var(--br-surface-muted)] px-2 py-1 text-[10px] font-bold">{project.category}</span><details className="relative"><summary className="grid size-8 cursor-pointer list-none place-items-center rounded-lg text-[var(--br-text-muted)] hover:bg-[var(--br-surface-muted)]"><ChevronDown size={15} /><span className="sr-only">Project actions</span></summary><div className="absolute right-0 z-10 mt-1 w-72 rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><form action={updateWorkspaceProject} className="space-y-2"><input type="hidden" name="id" value={project.id} /><input name="title" required defaultValue={project.title} className="field" /><textarea name="description" defaultValue={project.description ?? ""} rows={2} placeholder="Description" className="field" /><div className="grid grid-cols-2 gap-2"><select name="category" defaultValue={project.category} className="field"><option value="CONTENT">Content</option><option value="COURSE">Course</option><option value="LESSON">Lesson</option><option value="WORKSHEET">Worksheet</option><option value="ASSESSMENT">Assessment</option><option value="AUDIO">Audio</option><option value="RESEARCH">Research</option><option value="PERSONAL">Personal</option></select><select name="status" defaultValue={project.status} className="field"><option value="PLANNING">Planning</option><option value="ACTIVE">Active</option><option value="PAUSED">Paused</option><option value="COMPLETED">Completed</option><option value="ARCHIVED">Archived</option></select></div><BrenDateTimeField name="due_at" defaultValue={dateInputValue(project.due_at)} label="Due date and time" /><button className="w-full rounded-lg bg-[var(--br-brand)] px-3 py-2 text-sm font-bold text-on-dark">Save changes</button></form><form action={deleteWorkspaceProject} className="mt-2 border-t border-[var(--br-border)] pt-2"><input type="hidden" name="id" value={project.id} /><button className="w-full rounded-lg px-3 py-2 text-left text-sm font-semibold text-[var(--br-danger)] hover:bg-[var(--br-danger)]/10">Delete project</button></form></div></details></div></div><button type="button" onClick={() => onOpenProject(project.id)} className="mt-4 block w-full text-left break-words text-lg font-semibold hover:text-[var(--br-brand)]">{project.title}</button><p className="mt-1 line-clamp-2 text-sm leading-6 text-[var(--br-text-muted)]">{project.description || "No description yet."}</p><div className="mt-4 flex items-center justify-between text-xs font-semibold text-[var(--br-text-muted)]"><span>{project.status}</span><span>{project.due_at ? `Due ${new Date(project.due_at).toLocaleDateString()}` : "No due date"}</span></div></article>})}{!projects.length ? <div className="col-span-full"><Empty icon={FolderKanban} title="No projects yet" detail="Create a project from the top of this page." /></div> : null}</section>; }

function Notes({ notes, projects }: { notes: Note[]; projects: Project[] }) { return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_300px]"><section className="overflow-hidden rounded-2xl border border-[var(--br-border)] bg-surface shadow-sm"><div className="border-b border-[var(--br-border)] px-4 py-4 sm:px-5"><h2 className="font-semibold">Notes</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Ideas and teaching notes you want to keep close.</p></div><div className="divide-y divide-[var(--br-border)]">{notes.map((note) => <article key={note.id} className="flex items-start gap-3 px-4 py-4 sm:px-5"><NotebookPen size={18} className="mt-0.5 shrink-0 text-[var(--br-brand)]" /><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="break-words font-semibold">{note.title}</h2>{note.project_id ? <span className="rounded-full bg-[var(--br-brand)]/10 px-2 py-0.5 text-[10px] font-bold text-[var(--br-brand)]">{projects.find((project) => project.id === note.project_id)?.title}</span> : null}</div><ReadMoreText text={note.body} /><p className="mt-3 text-xs text-[var(--br-text-muted)]">Updated {new Date(note.updated_at).toLocaleDateString()}</p></div><details className="relative shrink-0"><summary className="grid size-8 cursor-pointer list-none place-items-center rounded-lg text-[var(--br-text-muted)] hover:bg-[var(--br-surface-muted)]"><Pencil size={14} /><span className="sr-only">Edit note</span></summary><div className="absolute right-0 z-10 mt-2 w-[min(18rem,calc(100vw-3rem))] rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><form action={updateWorkspaceNote} className="space-y-2"><input type="hidden" name="id" value={note.id} /><input name="title" required defaultValue={note.title} className="field" /><textarea name="body" rows={5} defaultValue={note.body} className="field" /><select name="project_id" className="field"><option value="">No project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><button className="w-full rounded-lg bg-[var(--br-brand)] px-3 py-2 text-sm font-bold text-on-dark">Save changes</button></form><form action={deleteWorkspaceNote} className="mt-2 border-t border-[var(--br-border)] pt-2"><input type="hidden" name="id" value={note.id} /><button className="w-full rounded-lg px-3 py-2 text-left text-sm font-semibold text-[var(--br-danger)] hover:bg-[var(--br-danger)]/10">Delete note</button></form></div></details></article>)}{!notes.length ? <div className="px-5 py-12"><Empty icon={NotebookPen} title="No notes yet" detail="Capture an idea with the form beside this list." /></div> : null}</div></section><InlineForm title="New note" action={createWorkspaceNote}><input name="title" required placeholder="Note title" className="field" /><textarea name="body" rows={6} placeholder="Write something useful…" className="field" /><select name="project_id" className="field"><option value="">No project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><button className="rounded-lg bg-[var(--br-action)] px-4 py-2.5 text-sm font-bold text-on-dark">Save note</button></InlineForm></div>; }

function Resources({ resources, projects }: { resources: Resource[]; projects: Project[] }) { return <div className="grid gap-5 xl:grid-cols-[minmax(0,1fr)_300px]"><section className="overflow-hidden rounded-2xl border border-[var(--br-border)] bg-surface shadow-sm"><div className="flex items-center justify-between gap-3 border-b border-[var(--br-border)] px-4 py-4 sm:px-5"><div><h2 className="font-semibold">Saved resources</h2><p className="mt-1 text-sm text-[var(--br-text-muted)]">Links, snippets, and references for your work.</p></div><span className="rounded-full bg-[var(--br-brand)]/10 px-2.5 py-1 text-xs font-bold text-[var(--br-brand)]">{resources.length}</span></div><div className="divide-y divide-[var(--br-border)]">{resources.map((resource) => <article key={resource.id} className="flex min-w-0 items-start gap-3 px-4 py-3.5 sm:px-5"><span className="grid size-8 shrink-0 place-items-center rounded-lg bg-[var(--br-action)]/10 text-[var(--br-action)]"><Link2 size={16} /></span><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h2 className="break-words text-sm font-semibold">{resource.title}</h2><span className="rounded-full bg-[var(--br-surface-muted)] px-2 py-0.5 text-[10px] font-bold text-[var(--br-text-muted)]">{resource.resource_type}</span>{resource.project_id ? <span className="rounded-full bg-[var(--br-brand)]/10 px-2 py-0.5 text-[10px] font-bold text-[var(--br-brand)]">{projects.find((project) => project.id === resource.project_id)?.title}</span> : null}</div>{resource.resource_type === "CODE" ? <pre className="mt-1 max-h-24 overflow-auto rounded-lg bg-dark p-2 text-xs text-white/80">{resource.value}</pre> : <a href={resource.value} target="_blank" rel="noreferrer" className="mt-1 block truncate text-sm font-semibold text-[var(--br-brand)]">{resource.value}</a>}{resource.description ? <p className="mt-1 truncate text-xs text-[var(--br-text-muted)]">{resource.description}</p> : null}</div><details className="relative shrink-0"><summary className="grid size-8 cursor-pointer list-none place-items-center rounded-lg text-[var(--br-text-muted)] hover:bg-[var(--br-surface-muted)]"><Pencil size={14} /><span className="sr-only">Edit resource</span></summary><div className="absolute right-0 z-10 mt-2 w-[min(18rem,calc(100vw-3rem))] rounded-xl border border-[var(--br-border)] bg-surface p-3 shadow-xl"><form action={updateWorkspaceResource} className="space-y-2"><input type="hidden" name="id" value={resource.id} /><input name="title" required defaultValue={resource.title} className="field" /><select name="resource_type" defaultValue={resource.resource_type} className="field"><option value="LINK">Link</option><option value="CODE">Code</option><option value="AUDIO">Audio</option><option value="BRENUP">BrenUp</option></select><textarea name="value" required rows={4} defaultValue={resource.value} className="field" /><input name="description" defaultValue={resource.description ?? ""} placeholder="Short description" className="field" /><button className="w-full rounded-lg bg-[var(--br-brand)] px-3 py-2 text-sm font-bold text-on-dark">Save changes</button></form><form action={deleteWorkspaceResource} className="mt-2 border-t border-[var(--br-border)] pt-2"><input type="hidden" name="id" value={resource.id} /><button className="w-full rounded-lg px-3 py-2 text-left text-sm font-semibold text-[var(--br-danger)] hover:bg-[var(--br-danger)]/10">Delete resource</button></form></div></details></article>)}{!resources.length ? <div className="px-5 py-12"><Empty icon={Link2} title="No resources yet" detail="Save useful links and code with the form beside this list." /></div> : null}</div></section><InlineForm title="Save resource" action={createWorkspaceResource}><input name="title" required placeholder="Resource title" className="field" /><select name="resource_type" className="field"><option value="LINK">Link</option><option value="CODE">Code</option><option value="AUDIO">Audio</option><option value="BRENUP">BrenUp</option></select><textarea name="value" required rows={4} placeholder="Paste a URL or code" className="field" /><input name="description" placeholder="Short description" className="field" /><select name="project_id" className="field"><option value="">No project</option>{projects.map((project) => <option key={project.id} value={project.id}>{project.title}</option>)}</select><button className="rounded-lg bg-[var(--br-action)] px-4 py-2.5 text-sm font-bold text-on-dark">Save resource</button></InlineForm></div>; }

function InlineForm({ title, action, children }: { title: string; action: (formData: FormData) => Promise<void>; children: React.ReactNode }) { return <form action={action} className="h-fit space-y-3 rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm"><h2 className="font-semibold">{title}</h2>{children}</form>; }
function Metric({ icon: Icon, label, value, tone }: { icon: typeof ListChecks; label: string; value: number; tone: string }) { return <div className="rounded-2xl border border-[var(--br-border)] bg-surface p-4 shadow-sm"><span className={`grid size-9 place-items-center rounded-lg ${metricTones[tone] || metricTones.purple}`}><Icon size={18} /></span><p className="mt-3 text-2xl font-bold">{value}</p><p className="mt-1 text-xs font-semibold uppercase tracking-wide text-[var(--br-text-muted)]">{label}</p></div>; }
function Empty({ icon: Icon, title, detail }: { icon: typeof ListChecks; title: string; detail: string }) { return <div className="grid min-h-40 place-items-center rounded-2xl border border-dashed border-[var(--br-border)] p-6 text-center"><div><Icon className="mx-auto text-[var(--br-text-muted)]" /><p className="mt-3 font-semibold">{title}</p><p className="mt-1 text-sm text-[var(--br-text-muted)]">{detail}</p></div></div>; }
